{
 "summary": "Two existence statements are formalized. (1) There are two finitely generated, countable, ICC groups with Kazhdan property (T) whose group von Neumann algebras are trace-preservingly *-isomorphic but which are not isomorphic as groups. (2) There are a group Λ and a sequence (Γ_n) of finitely generated property-(T) groups, all with group factor isomorphic to L(Λ), that are pairwise non-isomorphic and none isomorphic to Λ. The most important caveat is that (2) asserts ICC for Λ but only for *some* Γ_n (`∃ n, IsICC (Γ n)`), not for all; the paper's index-24^n commensurability claim is also not formalized.",
 "glossary": [
  {"decl": "CountableDiscreteGroup", "line": 7, "plain": "A group on a countable type in universe u.", "standard_concept": "countable discrete group", "matches_standard": "yes", "note": ""},
  {"decl": "IsICC", "line": 24, "plain": "G is infinite and every non-identity element has an infinite conjugacy class.", "standard_concept": "ICC group", "matches_standard": "yes", "note": ""},
  {"decl": "GroupsIsomorphic", "line": 27, "plain": "There exists a group isomorphism G ≃* H.", "standard_concept": "group isomorphism", "matches_standard": "yes", "note": ""},
  {"decl": "UnitaryRepresentation", "line": 30, "plain": "A group homomorphism G → U(B(H)) for a complex Hilbert space H.", "standard_concept": "unitary representation of a discrete group", "matches_standard": "yes", "note": "No continuity is needed because G is discrete."},
  {"decl": "HasAlmostInvariantUnitVectors", "line": 43, "plain": "For every finite K ⊆ G and every ε > 0 there is a unit vector ξ with ‖π(g)ξ − ξ‖ < ε for all g ∈ K.", "standard_concept": "almost invariant vectors", "matches_standard": "yes", "note": ""},
  {"decl": "HasKazhdanPropertyT", "line": 49, "plain": "Every unitary representation on a complex Hilbert space in universe u that has almost invariant unit vectors has a nonzero invariant vector.", "standard_concept": "Kazhdan property (T)", "matches_standard": "yes", "note": "Hilbert spaces are restricted to Type 0. This is harmless for countable groups, since one can reduce to cyclic (separable) subrepresentations."},
  {"decl": "leftRegularRepresentation", "line": 106, "plain": "(λ_g f)(h) = f(g⁻¹h) on ℓ²(G).", "standard_concept": "left regular representation", "matches_standard": "yes", "note": ""},
  {"decl": "vonNeumannClosure", "line": 124, "plain": "The double commutant (S ∪ S*)''.", "standard_concept": "von Neumann algebra generated by S", "matches_standard": "yes", "note": ""},
  {"decl": "GroupVonNeumannAlgebra", "line": 148, "plain": "L(G) = λ(G)'' ⊆ B(ℓ²G).", "standard_concept": "group von Neumann algebra", "matches_standard": "yes", "note": ""},
  {"decl": "canonicalTrace", "line": 156, "plain": "τ(x) = ⟨δ_1, x δ_1⟩.", "standard_concept": "canonical trace on L(G)", "matches_standard": "yes", "note": ""},
  {"decl": "IsNormalStarAlgEquiv", "line": 169, "plain": "The *-isomorphism and its inverse preserve suprema of arbitrary families of projections.", "standard_concept": "normal *-isomorphism", "matches_standard": "partly", "note": "This is an ad hoc encoding of normality. It is automatic for any *-isomorphism, so it is only an extra (satisfiable) requirement."},
  {"decl": "TracialGroupFactorsIsomorphic", "line": 187, "plain": "There is a *-algebra isomorphism L(G) ≅ L(H) that satisfies the normality condition above and preserves the canonical traces.", "standard_concept": "isomorphism of group von Neumann algebras L(G) ≅ L(H)", "matches_standard": "yes", "note": "The extra conditions are automatic for II_1 factors, where *-isomorphisms are normal and the trace is unique. They only strengthen an existential claim."}
 ],
 "lean_claims": [
  {"theorem": "exists_nonisomorphic_propertyT_icc_groups_with_isomorphic_factors", "line": 199, "plain": "There exist countable groups Γ, Λ with the following properties: both are finitely generated, both are ICC, both have property (T), L(Γ) ≅ L(Λ) (normal, trace-preserving *-isomorphism), and Γ ≇ Λ."},
  {"theorem": "exists_infinite_pairwise_nonisomorphic_propertyT_icc_groups_with_isomorphic_factors", "line": 208, "plain": "There exist a countable group Λ and countable groups Γ_n (n ∈ ℕ) with the following properties: Λ and all Γ_n are finitely generated; Λ is ICC; some Γ_n is ICC; Λ and all Γ_n have property (T); L(Γ_n) ≅ L(Λ) and L(Γ_m) ≅ L(Γ_n) for all m, n; Γ_m ≇ Γ_n for m ≠ n; and Λ ≇ Γ_n for all n."}
 ],
 "paper_claims": [
  {"ref": "Corollary 5.10 / negation of Conjecture 1.1", "plain": "There exist countable ICC property-(T) groups Λ, Γ_0 with L(Λ) ≅ L(Γ_0) and Λ ≇ Γ_0."},
  {"ref": "Theorem 1.2", "plain": "There exist f.g. ICC property-(T) groups Λ, Γ_0, Γ_1, … that are pairwise nonisomorphic with L(Γ_n) ≅ L(Λ) for all n. Moreover, Γ_n contains a subgroup isomorphic to Γ_0 of index 2^{4n}, so the Γ_n are commensurable."}
 ],
 "coverage": [
  {"paper_ref": "Corollary 5.10 / negation of Conjecture 1.1", "lean_theorem": "exists_nonisomorphic_propertyT_icc_groups_with_isomorphic_factors", "relation": "lean_stronger", "why": "It adds finite generation and normality/trace-preservation of the isomorphism; all of these hold for the paper's examples."},
  {"paper_ref": "Theorem 1.2 (main part)", "lean_theorem": "exists_infinite_pairwise_nonisomorphic_propertyT_icc_groups_with_isomorphic_factors", "relation": "lean_weaker", "why": "ICC is asserted for Λ but only for some Γ_n, not for every Γ_n."},
  {"paper_ref": "Theorem 1.2 (moreover: index 2^{4n} subgroups, commensurability)", "lean_theorem": null, "relation": "not_formalized", "why": "No subgroup or index statement appears."}
 ],
